INSERT OR REPLACE INTO translations (kind, ref, lang, text) VALUES
('agent', 'greeting', 'hi', 'नमस्ते जी, मैं DialMind से वान्या बोल रही हूँ। फसल का नुकसान हुआ है, सुनकर बहुत बुरा लगा। चिंता मत कीजिए, बस कुछ छोटे-छोटे सवाल पूछूँगी और आपका claim दर्ज कर दूँगी।'),
('agent', 'closing_filed', 'hi', 'हो गया जी, आपका claim दर्ज हो गया है। आपका claim नंबर है {claim_id}। SMS आ जाएगा, और {surveyor_date} तक surveyor आपके खेत पर आ जाएँगे। अपना ध्यान रखिए।'),
('agent', 'closing_area_based', 'hi', 'आपकी शिकायत दर्ज कर ली है। पूरे इलाके का आकलन होते ही SMS आ जाएगा। DialMind को call करने के लिए धन्यवाद।'),
('agent', 'closing_not_covered', 'hi', 'माफ़ कीजिए, ये नुकसान इस बीमा में नहीं आता। कुछ गड़बड़ लगे तो फसल बीमा helpline पर बात कर लीजिए। धन्यवाद।'),
('agent', 'repeat_question', 'hi', 'माफ़ कीजिए, बीच में आवाज़ कट गई। मैं फिर से पूछती हूँ।'),
('agent', 'not_understood', 'hi', 'माफ़ कीजिए, ठीक से सुन नहीं पाई।'),
('question', 'policy_ref', 'hi', 'अपना mobile नंबर बता दीजिए जो बीमा में दिया था, या फिर policy नंबर।'),
('question', 'confirm_identity', 'hi', 'अच्छा, {village} के {farmer_name} जी के नाम पर policy मिली है। ये आप ही हैं ना?'),
('question', 'crop_affected', 'hi', 'कौन सी फसल खराब हुई है? आपकी policy में {insured_crops} है।'),
('question', 'cause_of_loss', 'hi', 'नुकसान कैसे हुआ? ओले पड़े, बाढ़ आई, बेमौसम बारिश हुई, या जानवरों ने खराब किया?'),
('question', 'crop_stage', 'hi', 'उस वक़्त फसल खेत में खड़ी थी, या काटकर सुखाने रखी थी?'),
('question', 'loss_date', 'hi', 'ये किस दिन हुआ? कल, परसों, या कोई तारीख़ याद हो तो बताइए।'),
('question', 'late_reason', 'hi', '72 घंटे से ज़्यादा हो गए हैं। बताने में देर क्यों हुई, थोड़ा बता दीजिए?'),
('question', 'harvest_date', 'hi', 'फसल की कटाई कब की थी?'),
('question', 'affected_area', 'hi', 'कितनी ज़मीन पर नुकसान हुआ? एकड़ या गुंठा में बता दीजिए। आपका {crop} का खेत {insured_area} एकड़ का है।'),
('question', 'loss_percent', 'hi', 'अंदाज़े से बताइए, कितनी फसल खराब हो गई? आधी, पूरी, या कितने percent?'),
('question', 'confirm_sms', 'hi', 'Claim की जानकारी SMS पर {mobile_last4} वाले नंबर पर भेज दूँ?'),
('question', 'final_confirmation', 'hi', 'एक बार देख लीजिए: {summary}। सब सही है? Claim दर्ज कर दूँ?'),
('rule', 'R_POLICY_NOT_FOUND', 'hi', 'इस नंबर से कोई policy नहीं मिली। एक बार धीरे-धीरे फिर से बोलिए?'),
('rule', 'R_IDENTITY_DENIED', 'hi', 'कोई बात नहीं, दूसरा नंबर बताइए।'),
('rule', 'R_CROP_NOT_INSURED', 'hi', 'ये फसल आपकी policy में नहीं है जी। Policy में {insured_crops} है।'),
('rule', 'R_AREA_BASED_CAUSE', 'hi', 'सूखे और कीड़ों का नुकसान पूरे इलाके के लिए एक साथ देखा जाता है, इसके लिए अलग claim नहीं लगता। मैंने आपकी शिकायत लिख ली है।'),
('rule', 'R_WILD_ANIMAL_ADDON', 'hi', 'जंगली जानवरों का नुकसान तभी मिलता है जब आपके राज्य ने ये cover लिया हो। मैं दर्ज कर देती हूँ, बीमा कंपनी बता देगी।'),
('rule', 'R_FUTURE_DATE', 'hi', 'ये तो आगे की तारीख़ है। असल में किस दिन हुआ था?'),
('rule', 'R_BEFORE_SOWING', 'hi', 'ये तारीख़ बुवाई ({sowing_date}) से पहले की है। एक बार दिन फिर से बताइए?'),
('rule', 'R_LATE_INTIMATION', 'hi', 'वैसे नुकसान 72 घंटे के अंदर बताना होता है। मैं दर्ज कर रही हूँ, पर कंपनी देरी की वजह पूछ सकती है।'),
('rule', 'R_POST_HARVEST_WINDOW', 'hi', 'कटाई के बाद का नुकसान सिर्फ़ 14 दिन तक मिलता है, तो ये इसमें नहीं आएगा। माफ़ कीजिए।'),
('rule', 'R_AREA_EXCEEDS', 'hi', 'ये तो आपके {insured_area} एकड़ वाले {crop} के खेत से ज़्यादा है। उसमें कितना खराब हुआ?'),
('rule', 'R_HIGH_LOSS_PRIORITY', 'hi', 'नुकसान काफ़ी ज़्यादा है, तो surveyor की visit जल्दी करवा रही हूँ।'),
('agent', 'greeting', 'kn', 'ನಮಸ್ಕಾರ, ನಾನು DialMind ಇಂದ ವನ್ಯಾ ಮಾತಾಡ್ತಿದೀನಿ. ಬೆಳೆ ಹಾಳಾಯ್ತು ಅಂತ ಕೇಳಿ ತುಂಬಾ ಬೇಜಾರಾಯ್ತು. ಚಿಂತೆ ಮಾಡ್ಬೇಡಿ, ಸ್ವಲ್ಪ ಪ್ರಶ್ನೆ ಕೇಳ್ತೀನಿ, ನಿಮ್ಮ claim ಹಾಕಿಬಿಡ್ತೀನಿ.'),
('agent', 'closing_filed', 'kn', 'ಆಯ್ತು, ನಿಮ್ಮ claim ಹಾಕಿದೀನಿ. Claim ನಂಬರ್ {claim_id}. SMS ಬರುತ್ತೆ, {surveyor_date} ಒಳಗೆ surveyor ನಿಮ್ಮ ಹೊಲಕ್ಕೆ ಬರ್ತಾರೆ. ಹುಷಾರಾಗಿರಿ.'),
('agent', 'closing_area_based', 'kn', 'ನಿಮ್ಮ ದೂರು ಬರ್ಕೊಂಡಿದೀನಿ. ಊರಿನ ಅಂದಾಜು ಮುಗಿದ ತಕ್ಷಣ SMS ಬರುತ್ತೆ. DialMind ಗೆ call ಮಾಡಿದ್ದಕ್ಕೆ ಧನ್ಯವಾದ.'),
('agent', 'closing_not_covered', 'kn', 'ಕ್ಷಮಿಸಿ, ಈ ನಷ್ಟ ಈ ವಿಮೆಲಿ ಬರಲ್ಲ. ಏನಾದ್ರೂ ತಪ್ಪಾಗಿದೆ ಅನ್ಸಿದ್ರೆ ಬೆಳೆ ವಿಮೆ helpline ಗೆ call ಮಾಡಿ. ಧನ್ಯವಾದ.'),
('agent', 'repeat_question', 'kn', 'ಕ್ಷಮಿಸಿ, ಮಧ್ಯದಲ್ಲಿ ಮಾತು ಕಟ್ ಆಯ್ತು. ಮತ್ತೆ ಕೇಳ್ತೀನಿ.'),
('agent', 'not_understood', 'kn', 'ಕ್ಷಮಿಸಿ, ಸರಿಯಾಗಿ ಕೇಳಿಸ್ಲಿಲ್ಲ.'),
('question', 'policy_ref', 'kn', 'ವಿಮೆಗೆ ಕೊಟ್ಟಿರೋ mobile ನಂಬರ್ ಹೇಳಿ, ಇಲ್ಲಾಂದ್ರೆ policy ನಂಬರ್ ಹೇಳಿ.'),
('question', 'confirm_identity', 'kn', 'ಸರಿ, {village} ಊರಿನ {farmer_name} ಅವರ ಹೆಸರಲ್ಲಿ policy ಸಿಕ್ತು. ಅದು ನೀವೇನಾ?'),
('question', 'crop_affected', 'kn', 'ಯಾವ ಬೆಳೆ ಹಾಳಾಗಿದೆ? ನಿಮ್ಮ policy ಲಿ {insured_crops} ಇದೆ.'),
