('question', 'crop_stage', 'kn', 'ಆಗ ಬೆಳೆ ಹೊಲದಲ್ಲೇ ನಿಂತಿತ್ತಾ, ಇಲ್ಲಾ ಕಟಾವು ಮಾಡಿ ಒಣಗೋಕೆ ಹಾಕಿದ್ರಾ?'),
('question', 'loss_date', 'kn', 'ಯಾವತ್ತು ಆಯ್ತು? ನಿನ್ನೆ, ಮೊನ್ನೆ, ಇಲ್ಲಾ ದಿನಾಂಕ ನೆನಪಿದ್ರೆ ಹೇಳಿ.'),
('question', 'late_reason', 'kn', '72 ಗಂಟೆ ಮೇಲಾಗಿದೆ. ಹೇಳೋಕೆ ಯಾಕೆ ತಡ ಆಯ್ತು, ಸ್ವಲ್ಪ ಹೇಳಿ?'),
('question', 'harvest_date', 'kn', 'ಕಟಾವು ಯಾವತ್ತು ಮಾಡಿದ್ರಿ?'),
('question', 'affected_area', 'kn', 'ಎಷ್ಟು ಜಮೀನಲ್ಲಿ ಹಾಳಾಗಿದೆ? ಎಕರೆ ಇಲ್ಲಾ ಗುಂಟೆಲಿ ಹೇಳಿ. ನಿಮ್ಮ {crop} ಹೊಲ {insured_area} ಎಕರೆ ಇದೆ.'),
('question', 'loss_percent', 'kn', 'ಅಂದಾಜು ಎಷ್ಟು ಬೆಳೆ ಹೋಯ್ತು? ಅರ್ಧ, ಪೂರ್ತಿ, ಇಲ್ಲಾ ಎಷ್ಟು percent?'),
('question', 'confirm_sms', 'kn', 'Claim ವಿವರ {mobile_last4} ಇಂದ ಮುಗಿಯೋ ನಂಬರ್ಗೆ SMS ಕಳಿಸ್ಲಾ?'),
('question', 'final_confirmation', 'kn', 'ಒಂದ್ಸಲ ನೋಡಿ: {summary}. ಎಲ್ಲಾ ಸರಿ ಇದೆಯಾ? Claim ಹಾಕ್ಲಾ?'),
('rule', 'R_POLICY_NOT_FOUND', 'kn', 'ಈ ನಂಬರ್ಗೆ policy ಸಿಗ್ಲಿಲ್ಲ. ಒಂದ್ಸಲ ನಿಧಾನವಾಗಿ ಮತ್ತೆ ಹೇಳ್ತೀರಾ?'),
('rule', 'R_IDENTITY_DENIED', 'kn', 'ಪರವಾಗಿಲ್ಲ, ಬೇರೆ ನಂಬರ್ ಹೇಳಿ.'),
('rule', 'R_CROP_NOT_INSURED', 'kn', 'ಆ ಬೆಳೆ ನಿಮ್ಮ policy ಲಿ ಇಲ್ಲ. Policy ಲಿ {insured_crops} ಇದೆ.'),
('rule', 'R_AREA_BASED_CAUSE', 'kn', 'ಬರ, ಹುಳದ ನಷ್ಟ ಇಡೀ ಊರಿಗೆ ಒಟ್ಟಿಗೆ ಅಂದಾಜು ಮಾಡ್ತಾರೆ, ಬೇರೆ claim ಬೇಕಿಲ್ಲ. ನಿಮ್ಮ ದೂರು ಬರ್ಕೊಂಡಿದೀನಿ.'),
('rule', 'R_WILD_ANIMAL_ADDON', 'kn', 'ಕಾಡುಪ್ರಾಣಿ ನಷ್ಟ ರಾಜ್ಯ ಆ cover ತಗೊಂಡಿದ್ರೆ ಮಾತ್ರ ಸಿಗುತ್ತೆ. ಹಾಕ್ತೀನಿ, ವಿಮೆ company ಹೇಳುತ್ತೆ.'),
('rule', 'R_FUTURE_DATE', 'kn', 'ಅದು ಮುಂದಿನ ದಿನಾಂಕ. ನಿಜವಾಗ್ಲೂ ಯಾವತ್ತು ಆಯ್ತು?'),
('rule', 'R_BEFORE_SOWING', 'kn', 'ಆ ದಿನಾಂಕ ಬಿತ್ತನೆ ({sowing_date}) ಗಿಂತ ಮುಂಚೆ ಇದೆ. ದಿನ ಮತ್ತೆ ಹೇಳ್ತೀರಾ?'),
('rule', 'R_LATE_INTIMATION', 'kn', 'ನಷ್ಟ 72 ಗಂಟೆ ಒಳಗೆ ಹೇಳ್ಬೇಕು. ಹಾಕ್ತೀನಿ, ಆದ್ರೆ company ತಡ ಯಾಕೆ ಅಂತ ಕೇಳ್ಬಹುದು.'),
